/**
 * Runtime support for vecDSL programs generated for Redis Open Source with the Query Engine, through node-redis. Generated by
 * vecDSL 7. Do not edit.
 *
 * Every statement arrives as Redis command argument arrays built by the generator, identical in the Python, TypeScript and Java
 * programs; values travel as separate arguments or as PARAMS of a query, never inside a query string. Records are JSON documents
 * under the collection's key prefix. Writes read the affected documents under WATCH, compute the new documents and commit them
 * in one MULTI/EXEC, so a write is atomic and fails when another client changed a key in between. Replies are read in RESP2
 * through sendCommand, without the client's reply transformations.
 */
import { readFileSync } from "node:fs";
import { createClient } from "redis";

const DIGITS = 6;
const BATCH = 500;
const PAGE = 1000;
const TIMEOUT = 10_000;
const SEPARATORS = new Set(" \t,./(){}[]:;~!@#$%^&*-=+|'`\"<>?");
const MARKER = /\{\{(and|or|fuzzy1|fuzzy2|fuzzy3|prefix|prefixlast|tags):([A-Za-z0-9_]+)\}\}/g;
const SCORE = "vecdsl_score";
/** RediSearch's built-in stop-word list (src/stopwords.h), which an index uses unless STOPWORDS is given. */
const DEFAULT_STOPWORDS = ["a", "is", "the", "an", "and", "are", "as", "at", "be", "but", "by", "for", "if", "in", "into", "it", "no",
  "not", "of", "on", "or", "such", "that", "their", "then", "there", "these", "they", "this", "to", "was", "will", "with"];

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Doc = Record<string, Json>;
type Hit = Record<string, unknown>;

export class UnsupportedFeature extends Error {}

export class ConflictError extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

// ---------------------------------------------------------------- values

/** A number as text in one form for every host language: integers without a fraction, others in plain decimal notation. */
export function plain(value: number): string {
  if (!Number.isFinite(value)) {
    throw new Error("JSON has no infinite or NaN numbers");
  }
  if (Number.isInteger(value) && Math.abs(value) < 1e15) {
    return String(value);
  }
  const text = String(value);
  const match = /^(-?)(\d+)(?:\.(\d+))?e([+-]\d+)$/.exec(text);
  if (match === null) {
    return text;
  }
  const [, sign, whole, fraction = "", exponentText] = match;
  const exponent = Number(exponentText);
  const digits = whole + fraction;
  const point = whole.length + exponent;
  let result: string;
  if (point <= 0) {
    result = "0." + "0".repeat(-point) + digits;
  } else if (point >= digits.length) {
    result = digits + "0".repeat(point - digits.length);
  } else {
    result = digits.slice(0, point) + "." + digits.slice(point);
  }
  result = result.includes(".") ? result.replace(/0+$/, "").replace(/\.$/, "") : result;
  return sign + result.replace(/^0+(?=\d)/, "");
}

/** Compact JSON with numbers written by plain(), so that the three runtimes send identical documents. */
export function dumps(value: unknown): string {
  if (value === null || value === undefined) {
    return "null";
  }
  if (typeof value === "boolean") {
    return value ? "true" : "false";
  }
  if (typeof value === "number") {
    return plain(value);
  }
  if (typeof value === "string") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return "[" + value.map(dumps).join(",") + "]";
  }
  if (typeof value === "object") {
    return "{" + Object.entries(value as Record<string, unknown>).map(([key, item]) => JSON.stringify(key) + ":" + dumps(item)).join(",") + "}";
  }
  throw new TypeError(`cannot write ${typeof value} as JSON`);
}

function normalize(value: unknown): unknown {
  if (typeof value === "number") {
    return Number.isInteger(value) ? value : Number(value.toFixed(DIGITS));
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, normalize(item)]));
  }
  return value;
}

function argument(value: unknown): string {
  if (typeof value === "boolean") {
    return value ? "true" : "false";
  }
  if (typeof value === "number") {
    return plain(value);
  }
  if (typeof value === "string") {
    return value;
  }
  throw new TypeError(`a query parameter must be a string, number or boolean, not ${JSON.stringify(value)}`);
}

export function keyText(identifier: unknown): string {
  if (typeof identifier === "number") {
    return plain(identifier);
  }
  if (typeof identifier === "string") {
    return identifier;
  }
  throw new Error(`invalid record key ${JSON.stringify(identifier)}`);
}

function bfloat16(number: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setFloat32(0, number, true);
  const bits = view.getUint32(0, true);
  return ((bits + 0x7fff + ((bits >>> 16) & 1)) >>> 16) & 0xffff;
}

function float16(number: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setFloat32(0, number, true);
  const bits = view.getUint32(0, true);
  const sign = (bits >>> 16) & 0x8000;
  const exponent = (bits >>> 23) & 0xff;
  const mantissa = bits & 0x7fffff;
  if (exponent === 0xff) {
    return sign | 0x7c00 | (mantissa !== 0 ? 0x200 : 0);
  }
  const half = exponent - 112;
  if (half >= 0x1f) {
    return sign | 0x7c00;
  }
  const significand = half > 0 ? mantissa : mantissa | 0x800000;
  const shift = half > 0 ? 13 : 14 - half;
  if (shift > 24) {
    return sign;
  }
  const kept = significand >>> shift;
  const rest = significand - kept * 2 ** shift;
  const middle = 2 ** (shift - 1);
  const rounded = kept + (rest > middle || (rest === middle && (kept & 1) === 1) ? 1 : 0);
  return sign | (half > 0 ? (half << 10) + rounded : rounded);
}

/** A query vector as the little-endian bytes of the attribute's element type. */
export function blob(vector: number[], kind: string): Buffer {
  const sizes: Record<string, number> = { FLOAT32: 4, FLOAT64: 8, FLOAT16: 2, BFLOAT16: 2, INT8: 1, UINT8: 1 };
  const size = sizes[kind];
  if (size === undefined) {
    throw new Error(`unknown vector type ${kind}`);
  }
  const buffer = Buffer.alloc(size * vector.length);
  vector.forEach((item, index) => {
    const at = index * size;
    switch (kind) {
      case "FLOAT32":
        buffer.writeFloatLE(item, at);
        break;
      case "FLOAT64":
        buffer.writeDoubleLE(item, at);
        break;
      case "FLOAT16":
        buffer.writeUInt16LE(float16(item), at);
        break;
      case "BFLOAT16":
        buffer.writeUInt16LE(bfloat16(item), at);
        break;
      case "INT8":
        buffer.writeInt8(Math.trunc(item), at);
        break;
      default:
        buffer.writeUInt8(Math.trunc(item), at);
    }
  });
  return buffer;
}

/** The terms of a text as the Query Engine tokenizes it (separators of src/toksep.h), without the index's stop words. */
export function terms(text: string, stopwords: string[]): string[] {
  const result: string[] = [];
  let current = "";
  for (const character of text) {
    if (SEPARATORS.has(character)) {
      if (current) {
        result.push(current);
        current = "";
      }
    } else {
      current += character;
    }
  }
  if (current) {
    result.push(current);
  }
  const stop = new Set(stopwords.map((word) => word.toLowerCase()));
  return result.filter((term) => !stop.has(term.toLowerCase()));
}

// ---------------------------------------------------------------- connection

/** One RESP2 connection; the user and password come from the environment, never from the URL. */
export class Client {
  constructor(readonly redis: Redis) {}

  async call(args: Array<string | Buffer>): Promise<unknown> {
    const reply = await this.redis.sendCommand(args, { timeout: 3 * TIMEOUT });
    return decode(reply);
  }

  async close(): Promise<void> {
    if (this.redis.isOpen) {
      await this.redis.close();
    }
  }
}

function decode(reply: unknown): unknown {
  if (reply instanceof Error) {
    throw reply;
  }
  if (Buffer.isBuffer(reply)) {
    return reply.toString("utf8");
  }
  if (Array.isArray(reply)) {
    return reply.map(decode);
  }
  return reply;
}

function open(host: string, port: number, tls: boolean, username: string | undefined, password: string | undefined) {
  return createClient({
    socket: tls
      ? { host, port, tls: true, connectTimeout: TIMEOUT, reconnectStrategy: false }
      : { host, port, connectTimeout: TIMEOUT, reconnectStrategy: false },
    username,
    password,
    RESP: 2,
    disableOfflineQueue: true,
  });
}

type Redis = ReturnType<typeof open>;

export async function connect(args: { url: string; userVariable?: string; passwordVariable?: string }): Promise<Client> {
  const parsed = new URL(args.url);
  if (parsed.protocol !== "redis:" && parsed.protocol !== "rediss:") {
    throw new Error(`expected a redis:// or rediss:// URL, got ${args.url}`);
  }
  if (parsed.password !== "") {
    throw new Error("the connection URL must not contain a password; set it in the environment");
  }
  const database = parsed.pathname.replace(/^\//, "");
  if (database !== "" && database !== "0") {
    throw new Error("the Query Engine indexes only database 0 (FT.CREATE answers 'Cannot create index on db != 0')");
  }
  const user = process.env[args.userVariable ?? "VECDSL_REDIS_USER"] || (parsed.username ? decodeURIComponent(parsed.username) : undefined);
  const redis = open(parsed.hostname || "127.0.0.1", parsed.port ? Number(parsed.port) : 6379, parsed.protocol === "rediss:", user,
    process.env[args.passwordVariable ?? "VECDSL_REDIS_PASSWORD"]);
  redis.on("error", () => undefined);
  await redis.connect();
  return new Client(redis);
}

export async function command(client: Client, args: { args: string[]; ignore?: string[] }): Promise<unknown> {
  try {
    return await client.call(args.args);
  } catch (error) {
    const message = String((error as Error).message ?? error).toLowerCase();
    if ((args.ignore ?? []).some((phrase) => message.includes(phrase))) {
      return null;
    }
    throw error;
  }
}

/** Whether a lookup command (ACL GETUSER, for one) answers with a value rather than nil. */
export async function exists(client: Client, args: { args: string[] }): Promise<boolean> {
  return (await send(client, args.args)) !== null;
}

async function send(client: Client, args: Array<string | Buffer>): Promise<unknown> {
  return client.call(args);
}

/** Waits until the local append-only file has fsynced every write so far (WAITAOF 1 0, at most ten seconds). */
export async function durable(client: Client): Promise<void> {
  const [local] = (await send(client, ["WAITAOF", "1", "0", String(TIMEOUT)])) as number[];
  if (local < 1) {
    throw new Error("WAITAOF: the append-only file was not fsynced within ten seconds");
  }
}

// ---------------------------------------------------------------- documents

async function scan(client: Client, prefix: string): Promise<string[]> {
  const pattern = prefix.replace(/([*?[\]\\])/g, "\\$1") + "*";
  let cursor = "0";
  const keys = new Set<string>();
  for (;;) {
    const [next, page] = (await send(client, ["SCAN", cursor, "MATCH", pattern, "COUNT", String(PAGE)])) as [string, string[]];
    page.forEach((key) => keys.add(key));
    cursor = next;
    if (cursor === "0") {
      return [...keys].sort(compareText);
    }
  }
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

async function documents(client: Client, keys: string[]): Promise<Array<Doc | null>> {
  if (keys.length === 0) {
    return [];
  }
  const replies = (await send(client, ["JSON.MGET", ...keys, "$"])) as Array<string | null>;
  return replies.map((reply) => (reply === null ? null : (JSON.parse(reply) as Doc[])[0]));
}

function project(document: Doc, key: string, output: string[], vectors: string[], score: number | null): Hit {
  const hit: Hit = { id: document[key] ?? null };
  if (score !== null) {
    hit.score = score;
  }
  for (const name of [...output, ...vectors]) {
    hit[name] = document[name] ?? null;
  }
  return normalize(hit) as Hit;
}

class Plan {
  readonly docs = new Map<string, Doc | null>();
  readonly ttl = new Map<string, number>();
  readonly expire = new Map<string, number>();
  readonly changed: string[] = [];

  constructor(readonly client: Client) {}

  async load(keys: string[]): Promise<void> {
    const fresh = [...new Set(keys)].filter((key) => !this.docs.has(key));
    if (fresh.length === 0) {
      return;
    }
    await send(this.client, ["WATCH", ...fresh]);
    const found = await documents(this.client, fresh);
    for (let i = 0; i < fresh.length; i++) {
      this.docs.set(fresh[i], found[i]);
      this.ttl.set(fresh[i], (await send(this.client, ["PTTL", fresh[i]])) as number);
    }
  }

  put(key: string, document: Doc | null): void {
    this.docs.set(key, document);
    if (!this.changed.includes(key)) {
      this.changed.push(key);
    }
  }

  async commit(wait: boolean): Promise<void> {
    if (this.changed.length === 0) {
      await send(this.client, ["UNWATCH"]);
      return;
    }
    await send(this.client, ["MULTI"]);
    try {
      for (const key of this.changed) {
        const document = this.docs.get(key) ?? null;
        if (document === null) {
          await send(this.client, ["DEL", key]);
          continue;
        }
        await send(this.client, ["JSON.SET", key, "$", dumps(document)]);
        if (this.expire.has(key)) {
          await send(this.client, ["EXPIRE", key, String(this.expire.get(key))]);
        } else if ((this.ttl.get(key) ?? -1) > 0) {
          await send(this.client, ["PEXPIRE", key, String(this.ttl.get(key))]);
        }
      }
    } catch (error) {
      await send(this.client, ["DISCARD"]);
      throw error;
    }
    if ((await send(this.client, ["EXEC"])) === null) {
      throw new ConflictError("another client changed a written key during the write (WATCH); nothing was written");
    }
    if (wait) {
      await durable(this.client);
    }
  }
}

function recordDocument(record: Doc, key: string, vectors: Record<string, number>, slices?: Doc): Doc {
  if (record[key] === null || record[key] === undefined) {
    throw new Error(`a record without its key field ${key}`);
  }
  const document: Doc = {};
  for (const [name, item] of Object.entries(record)) {
    if (item !== null && item !== undefined) {
      document[name] = item;
    }
  }
  for (const [name, dim] of Object.entries(vectors)) {
    const vector = document[name];
    if (Array.isArray(vector) && vector.length !== dim) {
      throw new Error(`vector field ${name} has ${vector.length} dimensions, the index expects ${dim}`);
    }
  }
  return { ...document, ...(slices ?? {}) };
}

async function writeInto(plan: Plan, prefix: string, key: string, records: Doc[], policy: string, vectors: Record<string, number>,
  slices: Doc | undefined, ttl: number | undefined): Promise<number> {
  const docs = records.map((record) => recordDocument(record, key, vectors, slices));
  const keys = docs.map((document) => prefix + keyText(document[key]));
  if (policy === "error" && new Set(keys).size !== keys.length) {
    throw new Error("duplicate keys in one insert");
  }
  await plan.load(keys);
  let written = 0;
  for (let i = 0; i < keys.length; i++) {
    const existing = plan.docs.get(keys[i]);
    if (existing !== null && existing !== undefined && (policy === "error" || policy === "ignore")) {
      if (policy === "error") {
        throw new Error(`duplicate key ${keys[i]}`);
      }
      continue;
    }
    plan.put(keys[i], docs[i]);
    if (ttl !== undefined) {
      plan.expire.set(keys[i], ttl);
    }
    written += 1;
  }
  return written;
}

export interface WriteArgs {
  prefix: string;
  key: string;
  records: Doc[];
  policy: string;
  counter: string;
  vectors?: Record<string, number>;
  slices?: Doc;
  ttl?: number;
  wait?: boolean;
  batch_size?: number;
}

/** Writes records as documents in batches, each batch atomic; policy error, ignore or replace (update and upsert). */
export async function write(client: Client, args: WriteArgs): Promise<Record<string, number>> {
  const size = args.batch_size ?? BATCH;
  let total = 0;
  for (let start = 0; start < args.records.length; start += size) {
    const plan = new Plan(client);
    total += await writeInto(plan, args.prefix, args.key, args.records.slice(start, start + size), args.policy, args.vectors ?? {}, args.slices, args.ttl);
    await plan.commit(args.wait ?? false);
  }
  return { [args.counter]: total };
}

export interface Search {
  command: string[];
  reply?: string;
  params?: Record<string, unknown>;
  texts?: Record<string, unknown>;
  stopwords?: string[];
  blobs?: Record<string, string>;
  lookup?: Lookup;
  metric?: string;
}

interface Lookup {
  param: string;
  prefix: string;
  path: string;
  positive_ids?: unknown[];
  negative_ids?: unknown[];
  positive_vectors?: number[][];
  negative_vectors?: number[][];
}

async function select(client: Client, prefix: string, ids?: unknown[], search?: Search): Promise<string[]> {
  if (ids !== undefined) {
    return [...new Set(ids.map((identifier) => prefix + keyText(identifier)))];
  }
  if (search !== undefined) {
    return keysOf(client, search, undefined);
  }
  return scan(client, prefix);
}

interface Change {
  set?: Doc;
  append?: Record<string, Json[]>;
  remove?: Record<string, Json[]>;
  delete?: string[];
  replace?: { keep: string[] };
}

function same(left: Json, right: Json): boolean {
  return dumps(left) === dumps(right);
}

function change(document: Doc, edit: Change): Doc {
  let result: Doc = { ...document };
  if (edit.replace !== undefined) {
    const kept: Doc = {};
    for (const name of edit.replace.keep) {
      if (name in result) {
        kept[name] = result[name];
      }
    }
    result = kept;
  }
  for (const [name, item] of Object.entries(edit.set ?? {})) {
    if (item === null) {
      delete result[name];
    } else {
      result[name] = item;
    }
  }
  for (const [name, items] of Object.entries(edit.append ?? {})) {
    result[name] = [...((result[name] as Json[] | undefined) ?? []), ...items];
  }
  for (const [name, items] of Object.entries(edit.remove ?? {})) {
    const current = result[name];
    if (Array.isArray(current)) {
      result[name] = current.filter((item) => !items.some((removed) => same(item, removed)));
    }
  }
  for (const name of edit.delete ?? []) {
    delete result[name];
  }
  return result;
}

async function updateInto(plan: Plan, client: Client, prefix: string, key: string, edit: Change, ids?: unknown[], search?: Search,
  records?: Doc[]): Promise<number> {
  const byKey = new Map<string, Doc>();
  let targets: string[];
  if (records !== undefined) {
    records.forEach((record) => byKey.set(prefix + keyText(record[key]), record));
    const allowed = ids === undefined ? undefined : new Set(ids.map((identifier) => prefix + keyText(identifier)));
    targets = [...byKey.keys()].filter((name) => allowed === undefined || allowed.has(name));
  } else {
    targets = await select(client, prefix, ids, search);
  }
  await plan.load(targets);
  let updated = 0;
  for (const name of targets) {
    const document = plan.docs.get(name);
    if (document === null || document === undefined) {
      continue;
    }
    if (records !== undefined) {
      const given: Doc = {};
      for (const [field, item] of Object.entries(byKey.get(name) as Doc)) {
        if (field !== key) {
          given[field] = item;
        }
      }
      plan.put(name, change(document, { ...edit, set: given }));
    } else {
      plan.put(name, change(document, edit));
    }
    updated += 1;
  }
  return updated;
}

export interface UpdateArgs extends Change {
  prefix: string;
  key: string;
  ids?: unknown[];
  search?: Search;
  records?: Doc[];
  wait?: boolean;
}

/** Changes existing documents: set fields (null removes one), append to and remove from arrays, delete fields, replace. */
export async function update(client: Client, args: UpdateArgs): Promise<Record<string, number>> {
  const plan = new Plan(client);
  const count = await updateInto(plan, client, args.prefix, args.key, args, args.ids, args.search, args.records);
  await plan.commit(args.wait ?? false);
  return { update_count: count };
}

/** Deletes documents by key, by a filter (in key order, at most limit) or all documents under the prefix. */
export async function delete_(client: Client, args: { prefix: string; ids?: unknown[]; search?: Search; limit?: number; wait?: boolean }): Promise<Record<string, number>> {
  const keys = args.search !== undefined ? await keysOf(client, args.search, args.limit) : await select(client, args.prefix, args.ids);
  let count = 0;
  for (let start = 0; start < keys.length; start += PAGE) {
    count += (await send(client, ["DEL", ...keys.slice(start, start + PAGE)])) as number;
  }
  if (args.wait) {
    await durable(client);
  }
  return { delete_count: count };
}

export { delete_ as delete };

/** Writes by key of several statements in one MULTI/EXEC; each step sees the documents the earlier steps wrote. */
export async function transaction(client: Client, args: { steps: Array<Record<string, unknown>>; wait?: boolean }): Promise<unknown[]> {
  const plan = new Plan(client);
  const results: unknown[] = [];
  for (const step of args.steps) {
    const prefix = step.prefix as string;
    if (step.op === "write") {
      const count = await writeInto(plan, prefix, step.key as string, step.records as Doc[], step.policy as string,
        (step.vectors as Record<string, number> | undefined) ?? {}, step.slices as Doc | undefined, step.ttl as number | undefined);
      results.push({ [step.counter as string]: count });
    } else if (step.op === "update") {
      const count = await updateInto(plan, client, prefix, step.key as string, step as Change, step.ids as unknown[] | undefined, undefined,
        step.records as Doc[] | undefined);
      results.push({ update_count: count });
    } else {
      const names = [...new Set((step.ids as unknown[]).map((identifier) => prefix + keyText(identifier)))];
      await plan.load(names);
      let count = 0;
      for (const name of names) {
        const document = plan.docs.get(name);
        if (document !== null && document !== undefined) {
          plan.put(name, null);
          count += 1;
        }
      }
      results.push({ delete_count: count });
    }
  }
  await plan.commit(args.wait ?? false);
  return results;
}

export async function truncate(client: Client, args: { prefix: string }): Promise<Record<string, number>> {
  return delete_(client, { prefix: args.prefix });
}

/** FT.DROPINDEX without DD, then every key under the prefix (DD deletes only the documents the index holds). */
export async function dropCollection(client: Client, args: { index: string; prefix: string; if_exists?: boolean }): Promise<void> {
  if (!(args.if_exists && !((await send(client, ["FT._LIST"])) as string[]).includes(args.index))) {
    await send(client, ["FT.DROPINDEX", args.index]);
  }
  await truncate(client, { prefix: args.prefix });
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Doc[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Doc[];
  }
  return text.split(/\r?\n/).filter((line) => line.trim()).map((line) => JSON.parse(line) as Doc);
}

export async function importFile(client: Client, args: Omit<WriteArgs, "records"> & { location: string }): Promise<Record<string, number>> {
  return write(client, { ...args, records: await readRecords(client, { location: args.location }) });
}

// ---------------------------------------------------------------- queries

function expand(search: Search, vectors: Record<string, Buffer>): Array<string | Buffer> {
  const params = new Map<string, string | Buffer>();
  for (const [name, item] of Object.entries(search.params ?? {})) {
    params.set(name, argument(item));
  }
  const stopwords = search.stopwords ?? DEFAULT_STOPWORDS;
  const texts = search.texts ?? {};
  const replace = (_match: string, mode: string, name: string): string => {
    const value = texts[name];
    const found = mode === "tags" ? (value as unknown[]).map(argument) : terms(String(value), stopwords);
    if (found.length === 0) {
      throw new Error(`the text ${JSON.stringify(value)} has no terms to search for`);
    }
    found.forEach((term, index) => params.set(`${name}_${index}`, term));
    const names = found.map((_term, index) => `$${name}_${index}`);
    if (mode.startsWith("fuzzy")) {
      const marks = "%".repeat(Number(mode.slice(-1)));
      return names.map((item) => `${marks}${item}${marks}`).join(" ");
    }
    if (mode === "prefix") {
      return names.map((item) => `${item}*`).join(" ");
    }
    if (mode === "prefixlast") {
      names[names.length - 1] += "*";
    }
    return names.join(mode === "or" || mode === "tags" ? " | " : " ");
  };
  const args: Array<string | Buffer> = search.command.map((item) => item.replace(MARKER, replace));
  for (const [name, item] of Object.entries(vectors)) {
    params.set(name, item);
  }
  if (params.size > 0) {
    args.push("PARAMS", String(2 * params.size));
    for (const [name, item] of params) {
      args.push(name, item);
    }
  }
  return args;
}

async function queryVector(client: Client, lookup: Lookup): Promise<number[]> {
  const positives: number[][] = [...(lookup.positive_vectors ?? [])];
  const negatives: number[][] = [...(lookup.negative_vectors ?? [])];
  for (const [ids, target] of [[lookup.positive_ids ?? [], positives], [lookup.negative_ids ?? [], negatives]] as Array<[unknown[], number[][]]>) {
    const names = ids.map((identifier) => lookup.prefix + keyText(identifier));
    const found = await documents(client, names);
    names.forEach((name, index) => {
      const vector = found[index]?.[lookup.path];
      if (!Array.isArray(vector)) {
        throw new Error(`no vector ${lookup.path} stored under ${name}`);
      }
      target.push(vector as number[]);
    });
  }
  if (positives.length === 0) {
    throw new Error("no positive example to search with");
  }
  const mean = (vectors: number[][]): number[] => vectors[0].map((_item, i) => vectors.reduce((sum, vector) => sum + vector[i], 0) / vectors.length);
  const positive = mean(positives);
  if (negatives.length === 0) {
    return positive;
  }
  const negative = mean(negatives);
  return positive.map((item, i) => 2 * item - negative[i]);
}

function similarity(distance: number, metric: string | undefined, native: boolean): number {
  if (metric === undefined || native) {
    return distance;
  }
  if (metric === "euclidean") {
    return -Math.sqrt(Math.max(distance, 0));
  }
  return 1 - distance;
}

function pairs(reply: unknown[]): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (let i = 0; i + 1 < reply.length; i += 2) {
    result[String(reply[i])] = reply[i + 1];
  }
  return result;
}

async function scored(client: Client, search: Search): Promise<Array<[string, number | null]>> {
  const raw: Record<string, number[]> = {};
  if (search.lookup !== undefined) {
    raw[search.lookup.param] = await queryVector(client, search.lookup);
  }
  const blobs = search.blobs ?? {};
  const params: Record<string, unknown> = {};
  for (const [name, item] of Object.entries(search.params ?? {})) {
    if (name in blobs) {
      if (!(name in raw)) {
        raw[name] = item as number[];
      }
    } else {
      params[name] = item;
    }
  }
  const vectors: Record<string, Buffer> = {};
  for (const [name, kind] of Object.entries(blobs)) {
    vectors[name] = blob(raw[name], kind);
  }
  const reply = (await send(client, expand({ ...search, params }, vectors))) as unknown[];
  if (search.reply === "hybrid") {
    const fields = pairs(reply);
    return (fields.results as unknown[][]).map((row) => {
      const values = pairs(row);
      return [String(values.__key), Number(values.__score)];
    });
  }
  const rest = reply.slice(1);
  const result: Array<[string, number | null]> = [];
  if (search.reply === "scores") {
    for (let i = 0; i < rest.length; i += 2) {
      result.push([String(rest[i]), Number(rest[i + 1])]);
    }
  } else if (search.reply === "knn") {
    for (let i = 0; i < rest.length; i += 2) {
      result.push([String(rest[i]), Number(pairs(rest[i + 1] as unknown[])[SCORE])]);
    }
  } else {
    for (const row of rest as unknown[][]) {
      result.push([String(row[row.indexOf("__key") + 1]), null]);
    }
  }
  return result;
}

function paged(args: string[], offset: number, limit: number): string[] {
  const result = [...args];
  const at = result.indexOf("LIMIT");
  result.splice(at + 1, 2, String(offset), String(limit));
  return result;
}

/** Keys of the documents a filter matches, in key order: every page of an FT.AGGREGATE, or the first limit keys. */
async function keysOf(client: Client, search: Search, limit: number | undefined): Promise<string[]> {
  if (limit !== undefined) {
    return (await scored(client, { ...search, command: paged(search.command, 0, limit), reply: "keys" })).map(([name]) => name);
  }
  const keys: string[] = [];
  for (;;) {
    const found = (await scored(client, { ...search, command: paged(search.command, keys.length, PAGE), reply: "keys" })).map(([name]) => name);
    keys.push(...found);
    if (found.length < PAGE) {
      return keys;
    }
  }
}

async function hits(client: Client, found: Array<[string, number | null]>, key: string, output: string[], vectors: string[],
  metric: string | undefined, native: boolean, low?: number, high?: number): Promise<Hit[]> {
  const docs = await documents(client, found.map(([name]) => name));
  const result: Hit[] = [];
  found.forEach(([, score], index) => {
    const document = docs[index];
    if (document === null) {
      return;
    }
    const value = score === null ? null : similarity(score, metric, native);
    if (value !== null && ((low !== undefined && value < low) || (high !== undefined && value > high))) {
      return;
    }
    result.push(project(document, key, output, vectors, value));
  });
  return result;
}

export interface SearchArgs extends Search {
  reply: string;
  key: string;
  output: string[];
  vectors?: string[];
  native?: boolean;
  low?: number;
  high?: number;
  total?: Search;
}

/** A search built by the generator: the hits (id, score, output fields, vector fields), or {hits, total} with total. */
export async function search(client: Client, args: SearchArgs): Promise<unknown> {
  const found = await scored(client, args);
  const result = await hits(client, found, args.key, args.output, args.vectors ?? [], args.metric, args.native ?? false, args.low, args.high);
  return args.total === undefined ? result : { hits: result, total: await count(client, args.total) };
}

/** Documents in the order of an FT.AGGREGATE SORTBY: one page, or with every all pages from the command's offset. */
export async function scroll(client: Client, args: Search & { key: string; output: string[]; vectors?: string[]; every?: boolean }): Promise<Hit[]> {
  const definition: Search = { ...args, reply: "keys" };
  const names = args.every ? await keysOf(client, definition, undefined) : (await scored(client, definition)).map(([name]) => name);
  return hits(client, names.map((name) => [name, null]), args.key, args.output, args.vectors ?? [], undefined, false);
}

function order(identifier: unknown): [number, number | string] {
  return typeof identifier === "number" ? [0, identifier] : [1, String(identifier)];
}

function compareIds(left: unknown, right: unknown): number {
  const [a, b] = [order(left), order(right)];
  if (a[0] !== b[0]) {
    return a[0] - b[0];
  }
  return a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0;
}

/** Legs searched one by one and fused as vecDSL defines rrf (sum of 1/(k + rank)), weighted and relative_score; ties by key. */
export async function hybrid(client: Client, args: {
  legs: Array<Search & { reply: string }>; fusion: string; key: string; output: string[]; limit: number; offset?: number; k?: number; weights?: number[];
  vectors?: string[]; low?: number; high?: number;
}): Promise<Hit[]> {
  const weights = args.weights ?? args.legs.map(() => 1);
  const k = args.k ?? 60;
  const fused = new Map<string, number>();
  for (let i = 0; i < args.legs.length; i++) {
    const leg = args.legs[i];
    let values = (await scored(client, leg)).map(([name, score]): [string, number] => [name, similarity(score ?? 0, leg.metric, false)]);
    if (args.fusion === "relative_score" && values.length > 0) {
      const least = Math.min(...values.map(([, value]) => value));
      const most = Math.max(...values.map(([, value]) => value));
      values = values.map(([name, value]) => [name, most === least ? 1 : (value - least) / (most - least)]);
    }
    values.forEach(([name, value], index) => {
      const part = args.fusion === "rrf" ? 1 / (k + index + 1) : weights[i] * value;
      fused.set(name, (fused.get(name) ?? 0) + part);
    });
  }
  const names = [...fused.keys()];
  const docs = await documents(client, names);
  const found = new Map<string, Doc>();
  names.forEach((name, index) => {
    const document = docs[index];
    if (document !== null) {
      found.set(name, document);
    }
  });
  const ranked = [...found.keys()].sort((left, right) => (fused.get(right) as number) - (fused.get(left) as number)
    || compareIds((found.get(left) as Doc)[args.key], (found.get(right) as Doc)[args.key]));
  const result: Hit[] = [];
  for (const name of ranked) {
    const value = fused.get(name) as number;
    if ((args.low !== undefined && value < args.low) || (args.high !== undefined && value > args.high)) {
      continue;
    }
    result.push(project(found.get(name) as Doc, args.key, args.output, args.vectors ?? [], value));
  }
  const offset = args.offset ?? 0;
  return result.slice(offset, offset + args.limit);
}

/** The total of an FT.SEARCH with LIMIT 0 0. */
export async function count(client: Client, args: Search): Promise<number> {
  const reply = (await send(client, expand(args, {}))) as unknown[];
  return Number(reply[0]);
}

/** Documents by key, in the order of the ids; missing keys are skipped. */
/** Documents by key, in the order of the ids; missing keys are skipped, and documents outside the slices (attribute -> values). */
export async function get(client: Client, args: {
  prefix: string; key: string; ids: unknown[]; output: string[]; vectors?: string[]; slices?: Record<string, unknown[]>;
}): Promise<Hit[]> {
  const names = args.ids.map((identifier) => args.prefix + keyText(identifier));
  const inSlices = (document: Doc) => Object.entries(args.slices ?? {}).every(([attribute, values]) => values.includes(document[attribute]));
  return (await documents(client, names)).filter((document): document is Doc => document !== null && inSlices(document))
    .map((document) => project(document, args.key, args.output, args.vectors ?? [], null));
}

function shuffled<T>(items: T[], size: number): T[] {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy.slice(0, Math.min(size, copy.length));
}

/** first: the first records in key order; random: a uniform sample of the matching records (runs differ). */
export async function sample(client: Client, args: { prefix: string; key: string; size: number; output: string[]; search?: Search; first?: boolean }): Promise<Hit[]> {
  const keys = args.search !== undefined ? await keysOf(client, args.search, args.first ? args.size : undefined) : await scan(client, args.prefix);
  if (args.first && args.search === undefined) {
    const docs = (await documents(client, keys)).filter((document): document is Doc => document !== null);
    docs.sort((left, right) => compareIds(left[args.key], right[args.key]));
    return docs.slice(0, args.size).map((document) => project(document, args.key, args.output, [], null));
  }
  const chosen = args.first ? keys.slice(0, args.size) : shuffled(keys, args.size);
  return (await documents(client, chosen)).filter((document): document is Doc => document !== null)
    .map((document) => project(document, args.key, args.output, [], null));
}

/** Each sampled record with its nearest neighbours among the sample (canonical similarity, computed in the runtime). */
export async function distanceMatrix(client: Client, args: {
  prefix: string; key: string; field: string; metric: string; size: number; limit: number; search?: Search;
}): Promise<unknown[]> {
  const keys = args.search !== undefined ? await keysOf(client, args.search, undefined) : await scan(client, args.prefix);
  const chosen = (await documents(client, shuffled(keys, args.size))).filter((document): document is Doc => document !== null && Array.isArray(document[args.field]));
  const result: unknown[] = [];
  for (const left of chosen) {
    const u = left[args.field] as number[];
    const scores: Array<[number, Doc]> = [];
    for (const right of chosen) {
      if (right === left) {
        continue;
      }
      const v = right[args.field] as number[];
      let value: number;
      if (args.metric === "euclidean") {
        value = -Math.sqrt(u.reduce((sum, a, i) => sum + (a - v[i]) ** 2, 0));
      } else if (args.metric === "dot") {
        value = u.reduce((sum, a, i) => sum + a * v[i], 0);
      } else {
        const norms = Math.sqrt(u.reduce((sum, a) => sum + a * a, 0)) * Math.sqrt(v.reduce((sum, b) => sum + b * b, 0));
        value = norms ? u.reduce((sum, a, i) => sum + a * v[i], 0) / norms : 0;
      }
      scores.push([value, right]);
    }
    scores.sort((a, b) => b[0] - a[0] || compareIds(a[1][args.key], b[1][args.key]));
    for (const [value, right] of scores.slice(0, args.limit)) {
      result.push({ a: left[args.key], b: right[args.key], score: value });
    }
  }
  return normalize(result) as unknown[];
}

// ---------------------------------------------------------------- operations

/** FT.INFO as {name, prefix, attributes} with count and indexing state on request. */
export async function describe(client: Client, args: { index: string; stats?: boolean; progress?: boolean }): Promise<unknown> {
  const info = pairs((await send(client, ["FT.INFO", args.index])) as unknown[]);
  const definition = pairs(info.index_definition as unknown[]);
  const attributes = (info.attributes as unknown[][]).map((attribute) => {
    const fields: Record<string, unknown> = {};
    const rest = [...attribute];
    while (rest.length > 0) {
      const name = String(rest.shift());
      if (rest.length > 0 && ["identifier", "attribute", "type", "WEIGHT", "SEPARATOR", "algorithm", "data_type", "dim", "distance_metric", "M", "ef_construction"].includes(name)) {
        fields[name.toLowerCase()] = rest.shift();
      }
    }
    return { name: fields.attribute ?? null, path: fields.identifier ?? null, type: fields.type ?? null };
  });
  const result: Record<string, unknown> = { name: info.index_name, prefix: (definition.prefixes as string[] | undefined)?.[0] ?? null, attributes };
  if (args.stats) {
    result.count = Number(info.num_docs);
  }
  if (args.progress) {
    result.indexing = Number(info.indexing) !== 0;
    result.percent_indexed = Number(info.percent_indexed);
  }
  return normalize(result);
}

/** Polls FT.INFO until the background scan of existing keys has finished, at most timeout seconds. */
export async function awaitIndex(client: Client, args: { index: string; timeout?: number }): Promise<unknown> {
  const timeout = args.timeout ?? 60;
  const deadline = Date.now() + timeout * 1000;
  for (;;) {
    const info = pairs((await send(client, ["FT.INFO", args.index])) as unknown[]);
    if (Number(info.indexing) === 0) {
      return { index: args.index, state: "ready", percent_indexed: normalize(Number(info.percent_indexed)) };
    }
    if (Date.now() > deadline) {
      throw new Error(`index ${args.index} was still indexing after ${timeout} seconds`);
    }
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
}

/** collections and databases (from FT._LIST), aliases (FT.ALIASLIST), tag values of a slice attribute (FT.TAGVALS). */
export async function names(client: Client, args: {
  kind: string; prefix?: string; limit?: number; database?: string; index?: string; attribute?: string;
}): Promise<string[]> {
  let found: string[];
  if (args.kind === "collections") {
    const all = (await send(client, ["FT._LIST"])) as string[];
    found = all.filter((name) => (args.database === undefined ? !name.includes(":") : name.startsWith(args.database + ":")))
      .map((name) => (args.database === undefined ? name : name.slice(name.indexOf(":") + 1)));
  } else if (args.kind === "databases") {
    found = [...new Set(((await send(client, ["FT._LIST"])) as string[]).filter((name) => name.includes(":")).map((name) => name.split(":")[0]))];
  } else if (args.kind === "aliases") {
    found = args.index === undefined ? [] : ((await send(client, ["FT.ALIASLIST", args.index])) as string[]);
  } else if (args.kind === "indexes") {
    found = args.index === undefined ? [] : [args.index];
  } else {
    found = (await send(client, ["FT.TAGVALS", args.index as string, args.attribute as string])) as string[];
  }
  found = found.filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort(compareText);
  return args.limit === undefined ? found : found.slice(0, args.limit);
}

/** Drops the index without its documents and creates it again; the new index scans the existing keys in the background. */
export async function recreate(client: Client, args: { index: string; create: string[] }): Promise<void> {
  const aliases = ((await send(client, ["FT.ALIASLIST", args.index])) ?? []) as string[];
  await send(client, ["FT.DROPINDEX", args.index]);
  await send(client, args.create);
  for (const alias of aliases) {
    await command(client, { args: ["FT.ALIASADD", alias, args.index], ignore: ["alias already exists"] });
  }
}

/** Renames or removes fields in every document under the prefix (an alter of the collection), in batches. */
export async function rewrite(client: Client, args: { prefix: string; rename?: Record<string, string>; delete?: string[] }): Promise<Record<string, number>> {
  const keys = await scan(client, args.prefix);
  let changed = 0;
  for (let start = 0; start < keys.length; start += BATCH) {
    const plan = new Plan(client);
    const batch = keys.slice(start, start + BATCH);
    await plan.load(batch);
    for (const name of batch) {
      const document = plan.docs.get(name);
      if (document === null || document === undefined) {
        continue;
      }
      const updated: Doc = {};
      for (const [field, item] of Object.entries(document)) {
        if (!(args.delete ?? []).includes(field)) {
          updated[args.rename?.[field] ?? field] = item;
        }
      }
      if (dumps(updated) !== dumps(document)) {
        plan.put(name, updated);
        changed += 1;
      }
    }
    await plan.commit(false);
  }
  return { update_count: changed };
}

/** EXPIRE on every key under the prefix (a collection ttl set by alter; later writes set it themselves). */
export async function expire(client: Client, args: { prefix: string; seconds: number }): Promise<Record<string, number>> {
  let count = 0;
  for (const name of await scan(client, args.prefix)) {
    count += (await send(client, ["EXPIRE", name, plain(args.seconds)])) as number;
  }
  return { expire_count: count };
}

/** Copies (COPY) or renames (RENAME) every key under the prefix to the target prefix, then creates the target's index. */
export async function copyCollection(client: Client, args: { prefix: string; target: string; create: string[]; move?: boolean; drop?: string }): Promise<Record<string, number>> {
  const keys = await scan(client, args.prefix);
  for (const name of keys) {
    await send(client, [args.move ? "RENAME" : "COPY", name, args.target + name.slice(args.prefix.length)]);
  }
  if (args.drop !== undefined) {
    await send(client, ["FT.DROPINDEX", args.drop]);
  }
  await send(client, args.create);
  return { [args.move ? "moved_count" : "copied_count"]: keys.length };
}
